export declare const catsBody = "\n    <div class=\"cat-card\">\n        <h1>Meet Coco and Louis</h1>\n        <img src=\"/public/cat-images/bothCats.png\" alt=\"both cats img\" class=\"cat-photo\"/>\n        <p>\n            These fluffballs are my two year old Balinese cats. They're from the same litter of Balinese cats which we chose because of their hypoallergenic\n            properties (my dad and brother are allergic to most cats). They're spoiled and act like they run the place.\n        </p>\n    </div>\n\n    <div class=\"cat-card\">\n        <img src=\"/public/cat-images/coco1.png\" alt=\"coco img\" class=\"cat-photo\"/>\n        <h2>Coco</h2>\n        <p>\n            The smaller of the two, Coco is very affectionate and constantly begs for treats. She loves to bask in sunlight during the day and she chases small toys around the house by night. Louis often chases her but when he sits on her bed, she doesn't hesitate to bully him out.\n        </p>\n    </div>\n\n    <div class=\"cat-card\">\n        <img src=\"/public/cat-images/louis1.png\" alt=\"louis img\" class=\"cat-photo\"/>\n        <h2>Louis</h2>\n        <p>\n            Named after Louis Armstrong for his raspy voice, Louis is a lazy brick. Despite his beautiful looks, he often spends his days staring at walls and looking confused. It often seems like no thoughts occur behind his large eyes. He loves scratches around the neck and back, but clipping his claws is a nightmare!\n        </p>\n    </div>\n\n";
//# sourceMappingURL=cats.d.ts.map